sp_widget.client_script:
api.controller = function($window) {

    var c = this;

    // ==========================================
    // INITIAL DATA
    // ==========================================

    c.data.userName = "";
    c.data.userRole = "";
    c.profileMenuOpen = false;


    // ==========================================
    // GET LOGIN DATA FROM LOCAL STORAGE
    // ==========================================

    var campusLogin =
        localStorage.getItem("campusLogin");

    if (campusLogin) {

        try {

            var loginData =
                JSON.parse(campusLogin);

            if (loginData.userName) {

                c.data.userName =
                    loginData.userName;
            }

            if (loginData.userRole) {

                c.data.userRole =
                    loginData.userRole;
            }

        } catch (e) {

            console.error(
                "Error reading campusLogin:",
                e
            );
        }
    }


    // ==========================================
    // PROFILE MENU
    // ==========================================

    c.toggleProfileMenu = function() {

        c.profileMenuOpen =
            !c.profileMenuOpen;
    };


    // ==========================================
    // LOGOUT
    // ==========================================

    c.logout = function() {

        console.log(
            "========== LOGOUT STARTED =========="
        );

        var campusLogin =
            localStorage.getItem("campusLogin");


        // --------------------------------------
        // NO LOGIN DATA
        // --------------------------------------

        if (!campusLogin) {

            console.log(
                "No campusLogin found"
            );

            $window.location.href =
                "/food_services";

            return;
        }


        // --------------------------------------
        // READ SESSION
        // --------------------------------------

        try {

            var loginData =
                JSON.parse(campusLogin);

            var sessionId =
                loginData.sessionId;


            console.log(
                "Session ID:",
                sessionId
            );


            // ----------------------------------
            // SESSION ID MISSING
            // ----------------------------------

            if (!sessionId) {

                console.log(
                    "Session ID missing"
                );

                localStorage.removeItem(
                    "campusLogin"
                );

                $window.location.href =
                    "/food_services";

                return;
            }


            // ----------------------------------
            // CALL SERVER SCRIPT
            // ----------------------------------

            console.log(
                "Sending logout request to server..."
            );

            c.server.get({

                action: "logout",

                sessionId: sessionId

            }).then(function(response) {

                console.log(
                    "Logout server response:",
                    response
                );

                console.log(
                    "Logout result:",
                    response.data.logoutSuccess
                );


                // --------------------------------
                // REMOVE LOCAL SESSION
                // --------------------------------

                localStorage.removeItem(
                    "campusLogin"
                );

                console.log(
                    "campusLogin removed from localStorage"
                );


                // --------------------------------
                // REDIRECT TO LANDING PAGE
                // --------------------------------

                console.log(
                    "Redirecting to landing page..."
                );

                $window.location.href =
                    "/food_services";

            }).catch(function(error) {

                console.error(
                    "Logout server error:",
                    error
                );

                // Even if server fails,
                // remove local session
                // and return to landing page.

                localStorage.removeItem(
                    "campusLogin"
                );

                $window.location.href =
                    "/food_services";
            });


        } catch (e) {

            console.error(
                "Logout processing error:",
                e
            );

            localStorage.removeItem(
                "campusLogin"
            );

            $window.location.href =
                "/food_services";
        }

    };

};

sp_widget.css:
/* =========================================================
   MEALCARE — DASHBOARD SHARED HEADER CSS
   Professional Dark Frame Theme
   Used by Student, Staff, Admin and Manager dashboards
   HTML / Angular bindings unchanged
   ServiceNow Compatible
   ========================================================= */

.campus-header {
  position: relative;
  z-index: 1000;
  width: 100%;
  height: 74px;
  padding: 0 28px;
  box-sizing: border-box;
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-family: "Segoe UI", Arial, sans-serif;
  border-bottom: 1px solid #334155;
  background:
    radial-gradient(
      circle at 85% 0%,
      rgba(37, 99, 235, 0.22),
      transparent 42%
    ),
    linear-gradient(
      rgba(96, 165, 250, 0.025) 1px,
      transparent 1px
    ),
    linear-gradient(
      90deg,
      rgba(96, 165, 250, 0.025) 1px,
      transparent 1px
    ),
    #1E293B;
  background-size: auto, 48px 48px, 48px 48px, auto;
}

/* =========================================================
   BRAND
   ========================================================= */

.brand-section {
  display: flex;
  align-items: center;
  gap: 12px;
}

.brand-logo {
  width: 44px;
  height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(145deg, #60A5FA, #2563EB);
  border-radius: 12px;
  box-shadow: 0 8px 20px rgba(37, 99, 235, 0.30);
  font-size: 22px;
  transition: transform 0.25s ease, box-shadow 0.25s ease;
}

.brand-section:hover .brand-logo {
  transform: translateY(-2px);
  box-shadow: 0 10px 24px rgba(37, 99, 235, 0.38);
}

.brand-name {
  font-size: 24px;
  font-weight: 800;
  letter-spacing: -0.7px;
  color: #FFFFFF;
  white-space: nowrap;
}

/* =========================================================
   PROFILE
   ========================================================= */

.profile-section {
  position: relative;
}

.profile-button {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 7px 10px;
  background: transparent;
  border: 1px solid transparent;
  border-radius: 12px;
  cursor: pointer;
  transition:
    background-color 0.25s ease,
    border-color 0.25s ease,
    box-shadow 0.25s ease;
}

.profile-button:hover {
  background: rgba(255, 255, 255, 0.07);
  border-color: #475569;
  box-shadow: 0 4px 14px rgba(15, 23, 42, 0.20);
}

.user-name {
  font-size: 14px;
  font-weight: 700;
  color: #F8FAFC;
  white-space: nowrap;
}

.profile-icon {
  width: 38px;
  height: 38px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(145deg, #60A5FA, #2563EB);
  border-radius: 11px;
  box-shadow: 0 6px 16px rgba(37, 99, 235, 0.28);
  font-size: 18px;
}

.arrow {
  font-size: 10px;
  color: #94A3B8;
  transition:
    transform 0.25s ease,
    color 0.25s ease;
}

.profile-button:hover .arrow {
  color: #60A5FA;
}

.arrow.open {
  transform: rotate(180deg);
}

/* =========================================================
   PROFILE DROPDOWN
   ========================================================= */

.profile-dropdown {
  position: absolute;
  top: 58px;
  right: 0;
  width: 250px;
  padding: 10px;
  box-sizing: border-box;
  background: #FFFFFF;
  border: 1px solid #E2E8F0;
  border-radius: 14px;
  box-shadow: 0 20px 45px rgba(15, 23, 42, 0.22);
  animation: cfaDashDropdown 0.2s ease-out both;
}

/* =========================================================
   DROPDOWN USER
   ========================================================= */

.profile-user {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 10px;
}

.dropdown-user-icon {
  width: 40px;
  height: 40px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #EFF6FF;
  border: 1px solid #DBEAFE;
  border-radius: 10px;
  color: #2563EB;
  font-size: 18px;
}

.dropdown-user-name {
  font-size: 14px;
  font-weight: 800;
  color: #0F172A;
  line-height: 1.3;
}

.dropdown-user-role {
  margin-top: 3px;
  font-size: 12px;
  color: #64748B;
  line-height: 1.4;
}

/* =========================================================
   DIVIDER
   ========================================================= */

.dropdown-divider {
  height: 1px;
  margin: 6px 0;
  background: #E2E8F0;
}

/* =========================================================
   LOGOUT
   ========================================================= */

.logout-button {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 11px 10px;
  background: transparent;
  border: none;
  border-radius: 9px;
  cursor: pointer;
  font-family: "Segoe UI", Arial, sans-serif;
  font-size: 14px;
  font-weight: 700;
  color: #334155;
  text-align: left;
  transition:
    background-color 0.2s ease,
    color 0.2s ease,
    transform 0.2s ease;
}

.logout-button:hover {
  background: #EFF6FF;
  color: #1D4ED8;
  transform: translateX(3px);
}

/* =========================================================
   DROPDOWN ANIMATION
   ========================================================= */

@keyframes cfaDashDropdown {
  from {
    opacity: 0;
    transform: translateY(-6px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* =========================================================
   ACCESSIBILITY
   ========================================================= */

.campus-header button:focus-visible {
  outline: 2px solid #60A5FA;
  outline-offset: 3px;
  border-radius: 10px;
}

/* =========================================================
   RESPONSIVE — TABLET / SMALL DESKTOP
   ========================================================= */

@media (min-width: 992px) and (max-width: 1199px) {
  .campus-header {
    padding: 0 24px;
  }
}

/* =========================================================
   RESPONSIVE — TABLET
   ========================================================= */

@media (min-width: 768px) and (max-width: 991px) {
  .campus-header {
    height: 68px;
    padding: 0 24px;
  }

  .brand-name {
    font-size: 21px;
  }

  .brand-logo {
    width: 40px;
    height: 40px;
    font-size: 20px;
  }

  .user-name {
    font-size: 13px;
  }
}

/* =========================================================
   RESPONSIVE — LARGE MOBILE
   ========================================================= */

@media (min-width: 576px) and (max-width: 767px) {
  .campus-header {
    height: 66px;
    padding: 0 22px;
  }

  .brand-name {
    font-size: 20px;
  }

  .brand-logo {
    width: 38px;
    height: 38px;
    font-size: 19px;
  }

  .user-name {
    display: none;
  }

  .profile-dropdown {
    top: 54px;
    width: 230px;
  }
}

/* =========================================================
   RESPONSIVE — MOBILE
   ========================================================= */

@media (max-width: 575px) {
  .campus-header {
    height: 64px;
    padding: 0 18px;
  }

  .brand-name {
    font-size: 19px;
  }

  .brand-logo {
    width: 36px;
    height: 36px;
    font-size: 18px;
  }

  .user-name {
    display: none;
  }

  .profile-button {
    gap: 7px;
    padding: 5px 7px;
  }

  .profile-icon {
    width: 34px;
    height: 34px;
    font-size: 17px;
  }

  .profile-dropdown {
    top: 52px;
    right: -2px;
    width: 225px;
  }
}

/* =========================================================
   RESPONSIVE — VERY SMALL MOBILE
   ========================================================= */

@media (max-width: 399px) {
  .campus-header {
    height: 60px;
    padding: 0 15px;
  }

  .brand-name {
    font-size: 18px;
  }

  .brand-logo {
    width: 34px;
    height: 34px;
    font-size: 17px;
  }

  .profile-icon {
    width: 32px;
    height: 32px;
    font-size: 16px;
  }

  .profile-dropdown {
    top: 48px;
    width: 215px;
  }
}

/* =========================================================
   REDUCED MOTION
   ========================================================= */

@media (prefers-reduced-motion: reduce) {
  .campus-header *,
  .campus-header *::before,
  .campus-header *::after {
    animation: none !important;
    transition: none !important;
  }
}

sp_widget.script:
(function() {

    data.userName = "";
    data.userRole = "";
    data.logoutSuccess = false;

    // ==========================================
    // LOGOUT
    // ==========================================

    if (input && input.action == "logout") {

        var sessionId = input.sessionId;

        gs.info(
            "CAMPUS LOGOUT REQUEST RECEIVED. SESSION ID: " +
            sessionId
        );

        if (sessionId) {

            var sessionGR = new GlideRecord(
                "x_snc_campus_foo_1_campus_login_session"
            );

            sessionGR.addQuery(
                "session_id",
                sessionId
            );

            sessionGR.addQuery(
                "status",
                "active"
            );

            sessionGR.query();

            if (sessionGR.next()) {

                // Close the existing session
                sessionGR.setValue(
                    "status",
                    "logout"
                );

                sessionGR.setValue(
                    "end_time",
                    new GlideDateTime()
                );

                sessionGR.update();

                data.logoutSuccess = true;

                gs.info(
                    "CAMPUS SESSION CLOSED SUCCESSFULLY: " +
                    sessionId
                );

            } else {

                // Session already closed/not found
                data.logoutSuccess = true;

                gs.info(
                    "CAMPUS SESSION NOT FOUND OR ALREADY CLOSED: " +
                    sessionId
                );
            }

        } else {

            data.logoutSuccess = false;

            gs.info(
                "CAMPUS LOGOUT FAILED: SESSION ID MISSING"
            );
        }

        return;
    }

})();
